IF OBJECT_ID('dbo.Enrollments','U') IS NULL CREATE TABLE dbo.Enrollments(Id BIGINT IDENTITY PRIMARY KEY,CourseId BIGINT NOT NULL,StudentId BIGINT NOT NULL,EnrolledAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),StartedAt DATETIME2 NULL,CompletedAt DATETIME2 NULL,Status VARCHAR(30) NOT NULL DEFAULT 'ENROLLED',ProgressPercent DECIMAL(5,2) NOT NULL DEFAULT 0,FinalScore DECIMAL(8,2) NULL,LastAccessAt DATETIME2 NULL,CreatedBy BIGINT NOT NULL,CONSTRAINT FK_Enrollments_Course FOREIGN KEY(CourseId) REFERENCES dbo.Courses(Id),CONSTRAINT FK_Enrollments_Student FOREIGN KEY(StudentId) REFERENCES dbo.Users(Id),CONSTRAINT UQ_Enrollments UNIQUE(CourseId,StudentId),CONSTRAINT CK_Enrollments_Status CHECK(Status IN('ENROLLED','IN_PROGRESS','COMPLETED','CANCELLED')));
GO
IF OBJECT_ID('dbo.StudentLessonProgress','U') IS NULL CREATE TABLE dbo.StudentLessonProgress(Id BIGINT IDENTITY PRIMARY KEY,StudentId BIGINT NOT NULL,CourseId BIGINT NOT NULL,LessonId BIGINT NOT NULL,ProgressPercent DECIMAL(5,2) NOT NULL DEFAULT 0,Score DECIMAL(8,2) NOT NULL DEFAULT 0,AttemptCount INT NOT NULL DEFAULT 0,Completed BIT NOT NULL DEFAULT 0,CompletedAt DATETIME2 NULL,LastAccessAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,CONSTRAINT FK_LessonProgress_Student FOREIGN KEY(StudentId) REFERENCES dbo.Users(Id),CONSTRAINT FK_LessonProgress_Course FOREIGN KEY(CourseId) REFERENCES dbo.Courses(Id),CONSTRAINT FK_LessonProgress_Lesson FOREIGN KEY(LessonId) REFERENCES dbo.Lessons(Id),CONSTRAINT UQ_LessonProgress UNIQUE(StudentId,LessonId));
GO
IF OBJECT_ID('dbo.StudentVideoProgress','U') IS NULL CREATE TABLE dbo.StudentVideoProgress(Id BIGINT IDENTITY PRIMARY KEY,StudentId BIGINT NOT NULL,CourseId BIGINT NOT NULL,LessonId BIGINT NOT NULL,VideoId BIGINT NOT NULL,CurrentTimeSeconds DECIMAL(10,2) NOT NULL DEFAULT 0,MaxWatchedTimeSeconds DECIMAL(10,2) NOT NULL DEFAULT 0,WatchedSeconds DECIMAL(10,2) NOT NULL DEFAULT 0,WatchPercent DECIMAL(5,2) NOT NULL DEFAULT 0,Completed BIT NOT NULL DEFAULT 0,StartedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CompletedAt DATETIME2 NULL,LastAccessAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,RowVersion ROWVERSION,CONSTRAINT FK_VideoProgress_Student FOREIGN KEY(StudentId) REFERENCES dbo.Users(Id),CONSTRAINT FK_VideoProgress_Course FOREIGN KEY(CourseId) REFERENCES dbo.Courses(Id),CONSTRAINT FK_VideoProgress_Lesson FOREIGN KEY(LessonId) REFERENCES dbo.Lessons(Id),CONSTRAINT FK_VideoProgress_Video FOREIGN KEY(VideoId) REFERENCES dbo.Videos(Id),CONSTRAINT UQ_VideoProgress UNIQUE(StudentId,VideoId));
GO
IF OBJECT_ID('dbo.StudentAnswers','U') IS NULL CREATE TABLE dbo.StudentAnswers(Id BIGINT IDENTITY PRIMARY KEY,StudentId BIGINT NOT NULL,CourseId BIGINT NOT NULL,LessonId BIGINT NOT NULL,VideoId BIGINT NULL,InteractionId BIGINT NULL,QuestionId BIGINT NOT NULL,AttemptNumber INT NOT NULL,AnswerText NVARCHAR(MAX) NULL,IsCorrect BIT NULL,ScoreAwarded DECIMAL(8,2) NOT NULL DEFAULT 0,ReviewStatus VARCHAR(30) NOT NULL,AnsweredAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),TimeInVideoSeconds DECIMAL(10,2) NULL,TimeSpentSeconds INT NULL,ReviewedBy BIGINT NULL,ReviewedAt DATETIME2 NULL,ReviewerComment NVARCHAR(1000) NULL,CONSTRAINT FK_StudentAnswers_Student FOREIGN KEY(StudentId) REFERENCES dbo.Users(Id),CONSTRAINT FK_StudentAnswers_Course FOREIGN KEY(CourseId) REFERENCES dbo.Courses(Id),CONSTRAINT FK_StudentAnswers_Lesson FOREIGN KEY(LessonId) REFERENCES dbo.Lessons(Id),CONSTRAINT FK_StudentAnswers_Question FOREIGN KEY(QuestionId) REFERENCES dbo.Questions(Id));
GO
IF OBJECT_ID('dbo.StudentAnswerOptions','U') IS NULL CREATE TABLE dbo.StudentAnswerOptions(StudentAnswerId BIGINT NOT NULL,QuestionOptionId BIGINT NOT NULL,CONSTRAINT PK_StudentAnswerOptions PRIMARY KEY(StudentAnswerId,QuestionOptionId),CONSTRAINT FK_AnswerOptions_Answer FOREIGN KEY(StudentAnswerId) REFERENCES dbo.StudentAnswers(Id),CONSTRAINT FK_AnswerOptions_Option FOREIGN KEY(QuestionOptionId) REFERENCES dbo.QuestionOptions(Id));
GO
IF OBJECT_ID('dbo.LearningSessions','U') IS NULL CREATE TABLE dbo.LearningSessions(Id BIGINT IDENTITY PRIMARY KEY,SessionId UNIQUEIDENTIFIER NOT NULL UNIQUE DEFAULT NEWID(),StudentId BIGINT NOT NULL,CourseId BIGINT NOT NULL,LessonId BIGINT NOT NULL,VideoId BIGINT NULL,StartedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),EndedAt DATETIME2 NULL,WatchDurationSeconds INT NOT NULL DEFAULT 0,LastPositionSeconds DECIMAL(10,2) NOT NULL DEFAULT 0,MaxPositionSeconds DECIMAL(10,2) NOT NULL DEFAULT 0,SeekCount INT NOT NULL DEFAULT 0,PauseCount INT NOT NULL DEFAULT 0,InteractionCount INT NOT NULL DEFAULT 0,Completed BIT NOT NULL DEFAULT 0);
GO
